package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__findDeserializer_TriageGen2Test {

    private DeserializationContext ctxt;
    private TypeIdResolver idResolver;
    private JavaType baseType;
    private BeanProperty property;
    private Map<String, JsonDeserializer<Object>> deserializers;
    private TestTypeDeserializer testInstance;

    // Concrete implementation to test protected method
    private static class TestTypeDeserializer extends TypeDeserializerBase {
        protected Map<String, JsonDeserializer<Object>> _deserializers = new HashMap<>();
        protected JavaType _baseType;
        protected BeanProperty _property;

        protected TestTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                     boolean typeIdVisible, JavaType defaultImpl, BeanProperty property) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
            this._baseType = baseType;
            this._property = property;
        }

        @Override
        public TypeDeserializer forProperty(BeanProperty prop) {
            return null;
        }

        @Override
        public JsonTypeInfo.As getTypeInclusion() {
            return null;
        }

        // Overriding to allow access to internal state for testing
        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return super._findDefaultImplDeserializer(ctxt);
        }

        @Override
        protected JavaType _handleUnknownTypeId(DeserializationContext ctxt, String typeId, 
                                               TypeIdResolver idResolver, JavaType baseType) throws IOException {
            return super._handleUnknownTypeId(ctxt, typeId, idResolver, baseType);
        }

        // Expose protected method for testing
        public JsonDeserializer<Object> publicFindDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializer(ctxt, typeId);
        }

        // Mocking internal map access for the test
        public void setDeserializers(Map<String, JsonDeserializer<Object>> map) {
            this._deserializers = map;
        }

        // We need to use a subclass that actually implements the logic or uses mocks
        // Since _deserializers is private/protected in real class, we rely on the actual instance
    }

    // A real subclass to avoid complex reflection for the internal _deserializers map
    private static class RealTestTypeDeserializer extends TypeDeserializerBase {
        public final Map<String, JsonDeserializer<Object>> mockMap = new HashMap<>();
        public final JavaType baseType;
        public final BeanProperty property;

        public RealTestTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                      boolean typeIdVisible, JavaType defaultImpl, BeanProperty property) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
            this.baseType = baseType;
            this.property = property;
        }

        @Override public TypeDeserializer forProperty(BeanProperty prop) { return null; }
        @Override public JsonTypeInfo.As getTypeInclusion() { return null; }

        public JsonDeserializer<Object> testFind(DeserializationContext ctxt, String typeId) throws IOException {
            // Using reflection to access the private/protected field if necessary, 
            // but here we simulate the behavior or use the actual class if possible.
            // Since we are writing a unit test for the method logic:
            return _findDeserializer(ctxt, typeId);
        }
    }

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        idResolver = mock(TypeIdResolver.class);
        baseType = TypeFactory.defaultInstance().constructType(Object.class);
        property = mock(BeanProperty.class);

        when(ctxt.getTypeFactory()).thenReturn(TypeFactory.defaultInstance());
    }

    @Test
    public void testFindDeserializer_AlreadyExists() throws IOException {
        JsonDeserializer<Object> existing = mock(JsonDeserializer.class);
        RealTestTypeDeserializer tester = new RealTestTypeDeserializer(baseType, idResolver, "type", true, null, property);
        // We can't easily inject into the private _deserializers map without reflection
        // But we can test the logic flow.

        // For the sake of this test, we assume the method logic:
        // If _deserializers.get(typeId) != null, return it.
        // Since we can't inject into the private final map easily without reflection, 
        // we will focus on the branches where it is null.
    }

    @Test
    public void testFindDeserializer_TypeIdFound() throws IOException {
        String typeId = "com.example.MyClass";
        JavaType foundType = TypeFactory.defaultInstance().constructType(String.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        RealTestTypeDeserializer tester = new RealTestTypeDeserializer(baseType, idResolver, "type", true, null, property);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(foundType);
        when(ctxt.findContextualValueDeserializer(eq(foundType), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = tester.testFind(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }

    @Test
    public void testFindDeserializer_TypeIdNull_DefaultImplFound() throws IOException {
        String typeId = "unknown";
        RealTestTypeDeserializer tester = new RealTestTypeDeserializer(baseType, idResolver, "type", true, null, property);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);

        // To test _findDefaultImplDeserializer, we need to mock it. 
        // Since it's a protected method in the base class, we'll use a spy.
        RealTestTypeDeserializer spyTester = spy(tester);
        JsonDeserializer<Object> defaultDeser = mock(JsonDeserializer.class);
        doReturn(defaultDeser).when(spyTester)._findDefaultImplDeserializer(ctxt);

        JsonDeserializer<Object> result = spyTester.testFind(ctxt, typeId);

        assertEquals(defaultDeser, result);
    }

    @Test
    public void testFindDeserializer_TypeIdNull_DefaultImplNull_HandleUnknownTypeIdFound() throws IOException {
        String typeId = "unknown";
        JavaType actualType = TypeFactory.defaultInstance().constructType(String.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        RealTestTypeDeserializer tester = new RealTestTypeDeserializer(baseType, idResolver, "type", true, null, property);
        RealTestTypeDeserializer spyTester = spy(tester);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        doReturn(null).when(spyTester)._findDefaultImplDeserializer(ctxt);
        doReturn(actualType).when(spyTester)._handleUnknownTypeId(eq(ctxt), eq(typeId), eq(idResolver), any());
        when(ctxt.findContextualValueDeserializer(eq(actualType), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = spyTester.testFind(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }

    @Test
    public void testFindDeserializer_TypeIdNull_AllNull_ReturnsNull() throws IOException {
        String typeId = "unknown";
        RealTestTypeDeserializer tester = new RealTestTypeDeserializer(baseType, idResolver, "type", true, null, property);
        RealTestTypeDeserializer spyTester = spy(tester);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        doReturn(null).when(spyTester)._findDefaultImplDeserializer(ctxt);
        doReturn(null).when(spyTester)._handleUnknownTypeId(eq(ctxt), eq(typeId), eq(idResolver), any());

        JsonDeserializer<Object> result = spyTester.testFind(ctxt, typeId);

        assertNull(result);
    }

    @Test
    public void testFindDeserializer_SpecializedTypeLogic() throws IOException {
        String typeId = "String";
        // Create a base type that is a Map to trigger the specialized type logic
        JavaType mapBaseType = TypeFactory.defaultInstance().constructType(Map.class);
        JavaType stringType = TypeFactory.defaultInstance().constructType(String.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        RealTestTypeDeserializer tester = new RealTestTypeDeserializer(mapBaseType, idResolver, "type", true, null, property);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(stringType);
        // The logic: if (baseType != null && baseType.getClass() == type.getClass())
        // Since both are likely SimpleType or similar, this branch should be hit.

        when(ctxt.findContextualValueDeserializer(any(JavaType.class), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = tester.testFind(ctxt, typeId);

        // Verify that constructSpecializedType was called because baseType and type classes match
        verify(ctxt).getTypeFactory();
        assertEquals(expectedDeser, result);
    }

    @Test
    public void testFindDeserializer_BaseTypeNull_NoSpecialization() throws IOException {
        String typeId = "String";
        JavaType stringType = TypeFactory.defaultInstance().constructType(String.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        // baseType is null
        RealTestTypeDeserializer tester = new RealTestTypeDeserializer(null, idResolver, "type", true, null, property);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(stringType);
        when(ctxt.findContextualValueDeserializer(eq(stringType), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = tester.testFind(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }
}
